SELECT id, opened_date, status, NTILE(4) OVER (PARTITION BY DATE_TRUNC('MONTH', opened_date) ORDER BY balance, id) AS balance_bucket, SUM(balance) OVER (PARTITION BY DATE_TRUNC('week', opened_date) ORDER BY opened_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_balance, NTILE(4) OVER w_hist AS balance_bucket_2 FROM accounts WINDOW w_hist AS (PARTITION BY DATE_TRUNC('WEEK', opened_date), account_type ORDER BY balance, id)
